(1, 106, 'admin', 'مرحباً بالعام الدراسي الجديد', 'نتمنى لجميع الطلاب والمعلمين عاماً دراسياً موفقاً ومثمراً.', 'normal', 'all', NULL, '2026-02-26 05:29:43', '2026-03-04 05:29:43'),
(2, 106, 'admin', 'موعد الاختبارات الفصلية', 'تبدأ الاختبارات الفصلية بتاريخ 15/3/2026. يُرجى الاستعداد الجيد.', 'normal', 'all_students', NULL, '2026-03-01 05:29:43', '2026-03-04 05:29:43'),
(3, 106, 'admin', 'اجتماع أولياء الأمور', 'يُعقد اجتماع أولياء الأمور يوم الأحد القادم الساعة 10 صباحاً.', 'normal', 'all_parents', NULL, '2026-02-28 05:29:43', '2026-03-04 05:29:43'),
